export const SITE_PAGES: SitePage[] = [{"path":"/about","title":"About us","description":"Who builds Aloha Social, how it is funded and governed, and what the project is trying to be.","html":"<h2 id=\"about-us\">About us</h2>\n<p>Aloha Social is a fully open-source social network for Nextcloud. It is built in the open, published under the AGPL-3.0-or-later licence, and developed at <a href=\"https://github.com/AlohaSocial/social\">github.com/AlohaSocial/social</a>.</p>\n<h2 id=\"what-we-are-trying-to-be\">What we are trying to be</h2>\n<p>A social network that is good to be in. That sounds vague, so here is what it means in the code:</p>\n<ul>\n<li><strong>No scoreboard by default.</strong> Like, boost and follower counts are hidden. Less pressure, less comparison, less performing for strangers.</li>\n<li><strong>No advertising, no tracking.</strong> There is no ad server to feed, so nothing about your reading is measured on its behalf.</li>\n<li><strong>Every personalised feed explains itself.</strong> The For You feed says why each post is there, and you can edit the interests behind it or turn the feed off.</li>\n<li><strong>Complexity stays hidden.</strong> Federation is genuinely complicated. None of that complexity is handed to the person posting.</li>\n<li><strong>Design comes first.</strong> A real phone layout, a dark mode that is the same design, full keyboard navigation, sound and haptics that are optional, and respect for the system&#39;s reduced-motion setting.</li>\n</ul>\n<h2 id=\"why-nextcloud\">Why Nextcloud</h2>\n<p>Aloha Social is a Nextcloud app, not another service to run. That choice buys three things a separate network cannot:</p>\n<ol>\n<li><strong>No new account, no new password.</strong> The login people already have — including single sign-on and two-factor authentication — is the login.</li>\n<li><strong>The data stays where the organisation&#39;s data already is.</strong> Posts live next to the files, calendar and chat, on infrastructure the organisation controls and backs up under its own rules.</li>\n<li><strong>It is part of the workspace.</strong> Posts appear in unified search, links unfurl in Talk, Text and Deck, and notifications use the Nextcloud bell and mail digest.</li>\n</ol>\n<p>Read <a href=\"/nextcloud\">why built into Nextcloud</a> for the full list.</p>\n<h2 id=\"who-builds-it\">Who builds it</h2>\n<p>Aloha Social grew out of Nextcloud Social and is maintained by a small core team together with contributors from across the Nextcloud and fediverse communities. The project history, the full list of previous contributors and the current maintainers are published in <a href=\"https://github.com/AlohaSocial/social/blob/master/AUTHORS.md\">AUTHORS.md</a>.</p>\n<p>There is no closed core and no proprietary cloud service. Everything the app does is in the repository: server code, web client, translations, tests and documentation.</p>\n<h2 id=\"how-the-project-works\">How the project works</h2>\n<ul>\n<li><strong>Developed in the open.</strong> Issues, pull requests and design decisions are discussed on GitHub. Large changes are specified in the repository&#39;s <code>docs/</code> directory before they are built.</li>\n<li><strong>Tested continuously.</strong> Roughly 7,900 PHP tests and 4,000 JavaScript tests run against every change.</li>\n<li><strong>Documented from the code.</strong> The documentation on this site is published from the repository&#39;s own documents, split into short pages — every page links back to its source.</li>\n<li><strong>Federated, not siloed.</strong> Aloha Social speaks ActivityPub and the AT Protocol, so it talks to Mastodon, Bluesky, Pixelfed, PeerTube, GoToSocial and Akkoma without a bridge.</li>\n</ul>\n<h2 id=\"what-it-costs\">What it costs</h2>\n<p>Nothing. The software is free under AGPL-3.0-or-later: anyone may run it, inspect it, adapt it and contribute to it. A hosting provider may charge for running it; the licence does not allow anyone to charge for the right to use it.</p>\n<h2 id=\"take-part\">Take part</h2>\n<ul>\n<li><strong>Report a bug or ask for a feature</strong> — <a href=\"https://github.com/AlohaSocial/social/issues\">open an issue</a>.</li>\n<li><strong>Contribute code or translations</strong> — see the <a href=\"/docs/contributing\">contributing guide</a>.</li>\n<li><strong>Run it for your organisation</strong> — the <a href=\"/install\">installation guide</a> covers Nextcloud 34 to 36 with PHP 8.3 to 8.5.</li>\n<li><strong>Use the brand</strong> — logos, colours and the press boilerplate are on the <a href=\"/brand\">brand page</a>.</li>\n</ul>\n","toc":[{"id":"about-us","text":"About us","level":2},{"id":"what-we-are-trying-to-be","text":"What we are trying to be","level":2},{"id":"why-nextcloud","text":"Why Nextcloud","level":2},{"id":"who-builds-it","text":"Who builds it","level":2},{"id":"how-the-project-works","text":"How the project works","level":2},{"id":"what-it-costs","text":"What it costs","level":2},{"id":"take-part","text":"Take part","level":2}]},{"path":"/nextcloud","title":"Built into Nextcloud","description":"Why a social network that lives inside the workspace your organisation already runs beats another service to sign up for.","html":"<h2 id=\"built-into-nextcloud\">Built into Nextcloud</h2>\n<p>Aloha Social is a Nextcloud app. That is not a packaging detail — it changes what the product is, what it costs to run, and what it is allowed to know about you.</p>\n<h2 id=\"one-account-already-paid-for\">One account, already paid for</h2>\n<p>Your Nextcloud account <em>is</em> the account. No second sign-up, no second password, no profile to fill in twice.</p>\n<ul>\n<li>The login people already have is the login — including single sign-on and two-factor authentication, whichever the organisation has configured.</li>\n<li>Display name and avatar come from the Nextcloud account and are changed there.</li>\n<li>Where your organisation uses Nextcloud groups, those groups are already the right shape for team accounts and lists.</li>\n</ul>\n<p>For the people who are not Nextcloud users — customers, members of the public, contributors — a server can allow social-only accounts. They sign up for Aloha Social alone and get <strong>no access</strong> to files, chat, calendar or anything else. It can be open, need approval, or work by invitation.</p>\n<h2 id=\"your-data-stays-where-your-data-already-is\">Your data stays where your data already is</h2>\n<p>Posts live next to the files, calendar and chat, on infrastructure the organisation runs, in the database it already backs up under its own retention rules.</p>\n<ul>\n<li>No third party is asked to store anything. There is no map service, no GIF service, no analytics endpoint and no ad server.</li>\n<li>Photos have their Exif, XMP, IPTC and GPS metadata removed before they are stored, without re-encoding the image.</li>\n<li>Account keys are encrypted at rest with the instance secret, so a database dump on its own is not enough to impersonate anybody.</li>\n<li>Backups, retention, logging and access control follow the rules the organisation already has for everything else it runs.</li>\n</ul>\n<h2 id=\"it-is-part-of-the-workspace-not-next-to-it\">It is part of the workspace, not next to it</h2>\n<table>\n<thead>\n<tr>\n<th>In Nextcloud</th>\n<th>What Aloha Social does with it</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><strong>Files</strong></td>\n<td>Pick photos or videos in Files and post them, with no second upload. Replies to a photo appear in the file&#39;s comments.</td>\n</tr>\n<tr>\n<td><strong>Talk, Text, Deck</strong></td>\n<td>Links to posts unfurl in them.</td>\n</tr>\n<tr>\n<td><strong>Unified search</strong></td>\n<td>Posts appear in Nextcloud&#39;s search alongside files and notes.</td>\n</tr>\n<tr>\n<td><strong>Notifications</strong></td>\n<td>The bell and the mail digest you already have.</td>\n</tr>\n<tr>\n<td><strong>Translation</strong></td>\n<td>Translations use the organisation&#39;s own translation provider, labelled as machine translations.</td>\n</tr>\n<tr>\n<td><strong>Audit log</strong></td>\n<td>Moderation actions land beside every other administrative action.</td>\n</tr>\n<tr>\n<td><strong>Groups</strong></td>\n<td>A group can post as one account; group membership decides who may post from it, and the group automatically becomes a list to read.</td>\n</tr>\n</tbody></table>\n<h2 id=\"teams-and-organisations\">Teams and organisations</h2>\n<ul>\n<li><strong>Team accounts.</strong> A Nextcloud group posts as one shared identity. Who wrote each post stays internal — recorded for the team and for moderators, and shown to nobody else.</li>\n<li><strong>Social-only accounts.</strong> Public, members or customers get an Aloha Social account and nothing else.</li>\n<li><strong>Serious moderation.</strong> Silence, suspend and take down, all recorded in Nextcloud&#39;s audit log; a review queue for spam and for an account&#39;s first post; domain blocks that also clean up what a blocked server already sent; and a dashboard of how well delivery to other servers is working.</li>\n<li><strong>Built to scale.</strong> On a test server with 400,000 posts, the home timeline loads in 50 ms. Several delivery workers run in parallel, and a video quota can be set per account.</li>\n</ul>\n<h2 id=\"still-a-real-fediverse-server\">Still a real fediverse server</h2>\n<p>Being inside Nextcloud does not make it a walled garden:</p>\n<ul>\n<li>One account reaches Mastodon, Bluesky, Pixelfed, PeerTube, GoToSocial and Akkoma — people there can follow, reply to, quote and boost Aloha Social users, and the reverse works too.</li>\n<li>Every account is also a Bluesky account with a handle like <code>you.your.cloud</code>, without a bridge and without an app password.</li>\n<li>Posts can be imported from Mastodon, GoToSocial, Pixelfed and Instagram&#39;s export, exported again as a full archive, and moved in both directions.</li>\n<li>The web app works today, and the native Aloha apps for iPhone, Android, Windows, macOS and Linux connect to the same server.</li>\n</ul>\n<h2 id=\"running-it\">Running it</h2>\n<p>Aloha Social runs on Nextcloud 34 to 36 with PHP 8.3 to 8.5, installed from the Nextcloud App Store or built from source. It is AGPL-3.0-licensed and developed in the open.</p>\n<ul>\n<li><strong>You run it:</strong> the <a href=\"/install\">installation guide</a> takes an administrator from requirements to a federating server.</li>\n<li><strong>You use it:</strong> <a href=\"/get-started\">Get started</a> covers finding a server and your first post.</li>\n<li><strong>You want the detail:</strong> the <a href=\"/docs/admin\">administration guide</a> and the <a href=\"/docs/architecture\">architecture document</a> explain how.</li>\n</ul>\n","toc":[{"id":"built-into-nextcloud","text":"Built into Nextcloud","level":2},{"id":"one-account-already-paid-for","text":"One account, already paid for","level":2},{"id":"your-data-stays-where-your-data-already-is","text":"Your data stays where your data already is","level":2},{"id":"it-is-part-of-the-workspace-not-next-to-it","text":"It is part of the workspace, not next to it","level":2},{"id":"teams-and-organisations","text":"Teams and organisations","level":2},{"id":"still-a-real-fediverse-server","text":"Still a real fediverse server","level":2},{"id":"running-it","text":"Running it","level":2}]},{"path":"/privacy","title":"Privacy in Aloha Social","description":"What Aloha Social collects, where it is stored, what leaves your server, and the switches that change that.","html":"<h2 id=\"privacy-in-aloha-social\">Privacy in Aloha Social</h2>\n<p>Aloha Social has no advertising and no tracking, and nothing about your reading is measured on anybody&#39;s behalf. This page is the full account: what is stored, where it is stored, what leaves the server, and which settings change the answers.</p>\n<p>Your server&#39;s operator is the data controller. Where Aloha Social runs on your organisation&#39;s Nextcloud, that is your organisation — not the Aloha Social project, and not a company behind it.</p>\n<h2 id=\"what-is-stored-and-where\">What is stored, and where</h2>\n<p>Everything below sits in your Nextcloud&#39;s database and storage, on infrastructure your organisation runs and backs up.</p>\n<table>\n<thead>\n<tr>\n<th>Data</th>\n<th>Where it lives</th>\n<th>Leaves the server</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>Your posts, replies and media</td>\n<td>Nextcloud database and data directory</td>\n<td>Yes — to the servers of people who follow you, as ActivityPub</td>\n</tr>\n<tr>\n<td>Your profile, avatar and banner</td>\n<td>Nextcloud database</td>\n<td>Yes — served to anyone who asks, publicly</td>\n</tr>\n<tr>\n<td>Who you follow, who follows you</td>\n<td>Nextcloud database</td>\n<td>Yes — the follower list is public, as on every federated service</td>\n</tr>\n<tr>\n<td>Private notes you write about accounts</td>\n<td>Nextcloud database</td>\n<td>Never</td>\n</tr>\n<tr>\n<td>Your For You interests</td>\n<td>Nextcloud database</td>\n<td>Never</td>\n</tr>\n<tr>\n<td>Private statistics and read counts</td>\n<td>Nextcloud database</td>\n<td>Never</td>\n</tr>\n<tr>\n<td>Account keys</td>\n<td>Nextcloud database, encrypted with the instance secret</td>\n<td>Never</td>\n</tr>\n<tr>\n<td>Filters, mutes, blocks, notification policy</td>\n<td>Nextcloud database</td>\n<td>Never</td>\n</tr>\n</tbody></table>\n<h2 id=\"what-leaves-the-server-and-why\">What leaves the server, and why</h2>\n<p>Federation is the point of the product, so posts do travel. They travel the same way they do on Mastodon:</p>\n<ul>\n<li><strong>A public post</strong> is delivered to the servers of your followers, and is readable by anyone who asks your server for it.</li>\n<li><strong>A followers-only post</strong> is delivered only to followers, and requires a signed fetch to read.</li>\n<li><strong>A direct post</strong> is delivered only to the people it is addressed to.</li>\n<li><strong>Nothing is sent to a third party.</strong> There is no map service, no GIF service, no analytics endpoint and no ad server. Link previews are fetched by your server and are not federated.</li>\n</ul>\n<p>Delivery is signed with your server&#39;s keys and rate-limited. What a remote server receives is the same object your own followers receive — not a profile of you.</p>\n<h2 id=\"what-is-stripped-before-anything-is-sent\">What is stripped before anything is sent</h2>\n<ul>\n<li><strong>Photos lose their hidden data.</strong> Exif, XMP, IPTC and the GPS coordinates a phone quietly attaches are removed before a photo is stored or sent. The image is not re-encoded, so it keeps its quality and its colour profile.</li>\n<li><strong>HTML is sanitised on both ends.</strong> Remote HTML is stripped server-side before it reaches a timeline, and again in the browser before it is rendered.</li>\n<li><strong>The 881 built-in animated emoji</strong> are served from your own server. Nothing is loaded from Giphy or Tenor.</li>\n<li><strong>Places on posts are named by people</strong>, not looked up in a geolocation service. Nothing is ever sent to a map provider to work a location out.</li>\n</ul>\n<h2 id=\"your-for-you-feed-stays-yours\">Your For You feed stays yours</h2>\n<p>The optional For You feed learns only from what you may already read: a signal names a post by id and nothing else, and the hashtags behind it are read through the same visibility, block and mute filters the timelines use. No raw signal is kept, nothing is federated, and every route involved is your own.</p>\n<p>The interests it produces are shown back to you as a word cloud you can drag, pin, remove and add to — and to nobody else. An administrator can switch the feed off, or make it opt-in for the whole server.</p>\n<h2 id=\"what-is-hidden-by-default\">What is hidden by default</h2>\n<ul>\n<li><strong>Counts.</strong> Likes, boosts and follower counts are not shown unless you turn them on.</li>\n<li><strong>Read counts.</strong> Your statistics are visible to you and to nobody else.</li>\n<li><strong>Who wrote a team post.</strong> For a team account, the individual author is recorded for the team and for moderators, and shown to nobody else.</li>\n<li><strong>Reports.</strong> A report about somebody on another server is forwarded without exposing who reported them.</li>\n</ul>\n<h2 id=\"two-switches-worth-knowing-about\">Two switches worth knowing about</h2>\n<p><strong>Who may reach you</strong> (Settings → Notifications). Five questions, each answered <em>Allow</em> or <em>Hold for review</em>: people you do not follow, people who do not follow you, accounts under 30 days old, private mentions you did not ask for, and accounts this server has limited. A held notification is stored but never rings — no bell, no push, no mail. Held people can still write to you; their posts wait in Activities until you look.</p>\n<p><strong>AI content</strong> (Settings). One switch hides every post that says it was made with AI.</p>\n<h2 id=\"leaving\">Leaving</h2>\n<p>You are not locked in:</p>\n<ul>\n<li>A full export contains every post, picture and video, in Mastodon&#39;s archive layout.</li>\n<li>An account move is supported in both directions, and tells the people who follow you where you went.</li>\n<li>Past posts can be imported from Mastodon, GoToSocial, Pixelfed and Instagram&#39;s own export — imported posts do not flood anybody&#39;s timeline.</li>\n</ul>\n<h2 id=\"for-administrators\">For administrators</h2>\n<p>Two things an operator decides that change this page for everybody on the server:</p>\n<ul>\n<li><strong>Registration</strong> can be open, approval-based or invitation-only, and social-only accounts can be created for people who must get no access to files, chat or anything else.</li>\n<li><strong>Retention, domain blocks and review queues</strong> are operator settings. Domain blocks also clean up what a blocked server already sent.</li>\n</ul>\n<p>The <a href=\"/docs/admin\">administration guide</a> covers each of these, and the <a href=\"/docs/architecture-security\">security section of the architecture document</a> records exactly what is enforced in code.</p>\n<h2 id=\"questions\">Questions</h2>\n<p>This page summarises the product. The detail lives in the documentation — the <a href=\"/docs/user\">user guide</a>, the <a href=\"/docs/notify-why\">notification policy</a>, and the <a href=\"/docs/architecture\">architecture document</a>. Every one of those pages links back to its source in the repository, where the claims can be checked against the code.</p>\n","toc":[{"id":"privacy-in-aloha-social","text":"Privacy in Aloha Social","level":2},{"id":"what-is-stored-and-where","text":"What is stored, and where","level":2},{"id":"what-leaves-the-server-and-why","text":"What leaves the server, and why","level":2},{"id":"what-is-stripped-before-anything-is-sent","text":"What is stripped before anything is sent","level":2},{"id":"your-for-you-feed-stays-yours","text":"Your For You feed stays yours","level":2},{"id":"what-is-hidden-by-default","text":"What is hidden by default","level":2},{"id":"two-switches-worth-knowing-about","text":"Two switches worth knowing about","level":2},{"id":"leaving","text":"Leaving","level":2},{"id":"for-administrators","text":"For administrators","level":2},{"id":"questions","text":"Questions","level":2}]},{"path":"/protect","title":"How Aloha Social protects you","description":"The defaults, filters, queues and moderation tools that keep a timeline calm — and the switches that change them.","html":"<h2 id=\"how-aloha-social-protects-you\">How Aloha Social protects you</h2>\n<p>Protection in Aloha Social is mostly a matter of defaults. This page collects everything the app does on your behalf before you touch a setting, and everything you can change afterwards.</p>\n<h2 id=\"the-defaults-that-are-already-on\">The defaults that are already on</h2>\n<p><strong>No scoreboard.</strong> Like, boost and follower counts are hidden unless you turn them on. The timeline has no engagement-ranked feed — posts arrive newest first, in full.</p>\n<p><strong>Calm notifications.</strong> Every new account starts with the calm policy:</p>\n<table>\n<thead>\n<tr>\n<th>Who is writing to you</th>\n<th>On a new account</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>People you do not follow</td>\n<td>Held for review</td>\n</tr>\n<tr>\n<td>People who do not follow you</td>\n<td>Allowed</td>\n</tr>\n<tr>\n<td>Accounts under 30 days old</td>\n<td>Held for review</td>\n</tr>\n<tr>\n<td>Private mentions you did not ask for</td>\n<td>Held for review</td>\n</tr>\n<tr>\n<td>Accounts this server limited</td>\n<td>Held for review</td>\n</tr>\n</tbody></table>\n<p>A held notification is stored and never raised: no bell, no push, no mail, and it does not count towards a digest. The person can still write to you — their message waits in Activities, under a line that says how many people are waiting, until you accept or dismiss it. Accepting puts them on your always-allowed list; nobody is ever told they were held.</p>\n<p><strong>Quiet hours and digests.</strong> Notifications are collected and delivered at the times you choose, so the phone does not light up at three in the morning.</p>\n<p><strong>Photos lose their location.</strong> Exif, XMP, IPTC and GPS data are stripped from every image before it is stored or sent, without re-encoding it.</p>\n<p><strong>No third parties.</strong> No map service, no GIF service, no tracker, no advertising. The 881 built-in emoji are served from your server.</p>\n<p><strong>AI content.</strong> One switch in Settings hides every post that says it was made with AI.</p>\n<h2 id=\"filtering-before-anything-reaches-you\">Filtering, before anything reaches you</h2>\n<p><strong>Filtered words</strong> apply to every timeline this app draws. A matching post is folded behind the filter&#39;s name or taken out altogether, and a filter can expire on its own. Filters are yours: they are stored on the server, visible to nobody else, and you can have as many as you like with different rules.</p>\n<p><strong>Mute a conversation</strong> from any post in a thread. Notifications for that thread stop entirely — bell, push and mail — and the thread stops appearing in Activities. The posts stay on every timeline, so you can still read what you choose to read. Unmuting restores what arrived meanwhile without ringing for it.</p>\n<p><strong>Hide a whole server.</strong> A per-user domain block takes out everything from one domain, for you, without an administrator being involved.</p>\n<p><strong>Hide somebody&#39;s boosts</strong>, or ask to be told when they post — both sit beside the bell on their profile.</p>\n<p><strong>Block and mute.</strong> Blocking severs the relationship in both directions and hides somebody everywhere. Muting hides them from your timelines and optionally your notifications, for an hour, a day, seven days, thirty, or until you lift it — and they are never told.</p>\n<h2 id=\"before-anybody-sees-it\">Before anybody sees it</h2>\n<p>Two rules hold a post back on the server side instead of publishing it:</p>\n<ul>\n<li><strong>First-post review</strong> holds the first post of an account that has published nothing yet. Administrators&#39; own posts are never held. It is off on a server where administrators created the accounts, and on where registration is open.</li>\n<li><strong>Autospam</strong> holds a post that trips a deliberately short list of rules: more than five links in a short post, or more than five mentions from an account nobody follows and that follows nobody. There is no wordlist and no score — &quot;seven links&quot; is something a moderator can agree or disagree with in a second.</li>\n</ul>\n<p><strong>A direct message is never held.</strong> Holding one would put private correspondence in front of a moderator who was not written to, for a machine&#39;s reason.</p>\n<p>A held post is stored as the request the client sent, not as a post: it is in no timeline, no profile, no outbox and no search — not even its author&#39;s. Their own copy sits in Settings, where they can take it back.</p>\n<h2 id=\"for-moderators\">For moderators</h2>\n<p>Five actions, in order of weight, all reversible except the last two:</p>\n<table>\n<thead>\n<tr>\n<th>Action</th>\n<th>What it costs</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><strong>Warn</strong></td>\n<td>Nothing. The account is told there is a problem.</td>\n</tr>\n<tr>\n<td><strong>Mark everything sensitive</strong></td>\n<td>Every future post is shown behind a click.</td>\n</tr>\n<tr>\n<td><strong>Silence</strong></td>\n<td>The account leaves the public and global timelines. Deliberate followers still see it.</td>\n</tr>\n<tr>\n<td><strong>Take down</strong></td>\n<td>One post is deleted, everywhere it reached.</td>\n</tr>\n<tr>\n<td><strong>Suspend</strong></td>\n<td>Everything posted here is deleted, follows go both ways, and further sends are refused.</td>\n</tr>\n</tbody></table>\n<p>Every action names the moderator who took it. With Nextcloud&#39;s audit app enabled they land in the audit log beside every other administrative action. The strike history is never rewritten by a lift.</p>\n<p>Domain blocks work the same way at the level of a server, and clean up what a blocked server already sent.</p>\n<p>The <a href=\"/docs/admin-moderating\">administration guide</a> documents moderation, and the <a href=\"/features/safety\">safety feature page</a> shows the controls as a person meets them.</p>\n<h2 id=\"under-the-hood\">Under the hood</h2>\n<p>A page of detail for the technically curious — the <a href=\"/docs/architecture-security\">security section of the architecture document</a> records all of it, with the class and method names:</p>\n<ul>\n<li>every outbound delivery is signed with the sending actor&#39;s key, and inbound ones are verified against the request target, host, date and digest, with a replay window;</li>\n<li>inbound deliveries are rate-limited twice — once by source address, once by verified origin — and bodies are capped at 1 MiB;</li>\n<li>actor private keys are encrypted at rest with the instance secret, so a database dump alone is not enough to impersonate anybody;</li>\n<li>client secrets, authorization codes and access tokens are stored hashed;</li>\n<li>outbound requests refuse private, loopback and otherwise reserved addresses, and re-check on every redirect;</li>\n<li>JSON-LD contexts are served from the copies shipped with the app, never fetched for signature work;</li>\n<li>an attachment from another server cannot overwrite a document this server owns.</li>\n</ul>\n<h2 id=\"where-to-go-next\">Where to go next</h2>\n<ul>\n<li><a href=\"/features/safety\">The safety feature page</a> — the same controls as you meet them in the app.</li>\n<li><a href=\"/docs/notify-behaviour\">Who may reach you</a> — the notification policy in detail.</li>\n<li><a href=\"/privacy\">Privacy in Aloha Social</a> — what is stored, what leaves the server, and why.</li>\n<li><a href=\"/rules\">Rules for using Aloha Social</a> — what is expected of people here.</li>\n</ul>\n","toc":[{"id":"how-aloha-social-protects-you","text":"How Aloha Social protects you","level":2},{"id":"the-defaults-that-are-already-on","text":"The defaults that are already on","level":2},{"id":"filtering-before-anything-reaches-you","text":"Filtering, before anything reaches you","level":2},{"id":"before-anybody-sees-it","text":"Before anybody sees it","level":2},{"id":"for-moderators","text":"For moderators","level":2},{"id":"under-the-hood","text":"Under the hood","level":2},{"id":"where-to-go-next","text":"Where to go next","level":2}]},{"path":"/rules","title":"Rules for using Aloha Social","description":"What is expected of people here, what is not tolerated, and how moderation works on a server running the app.","html":"<h2 id=\"rules-for-using-aloha-social\">Rules for using Aloha Social</h2>\n<p>Aloha Social runs on many servers, and each server sets its own rules for the people it hosts. This page is the baseline: what the app assumes, what it is built to prevent, and what you can expect from the people who run your server.</p>\n<p>Your server&#39;s own rules take precedence. Before you post somewhere new, read the rules that server publishes — the <a href=\"/servers\">find a server</a> page links to them.</p>\n<h2 id=\"the-baseline\">The baseline</h2>\n<p><strong>Be a person, not a campaign.</strong> Spam, coordinated inauthentic behaviour and undisclosed automation are the fastest way to lose an account. The server holds a first post for review where registration is open, and holds posts that look like link or mention floods.</p>\n<p><strong>Do not harass people.</strong> Targeted abuse, dogpiling, unwanted sexual attention and publishing private information are reportable everywhere in the fediverse. Blocks, mutes and filters exist so people can protect themselves first and report second.</p>\n<p><strong>Do not post illegal content.</strong> Content that is illegal where the server operates is removed, and the server&#39;s operator may be obliged to act on it.</p>\n<p><strong>Respect the audience people chose.</strong> A followers-only or direct post is addressed to a particular audience. Screenshotting it into public is a betrayal of that choice, even where the software cannot prevent it.</p>\n<p><strong>Label what needs labelling.</strong> Use content warnings for spoilers and difficult material, alt text for pictures, and the AI label when a post says it was made with AI. The composer asks; the answer is never blocked, but the nudge is deliberate.</p>\n<p><strong>Nothing here is anonymous.</strong> Your posts carry your handle and your server. Reports about accounts on other servers are forwarded without exposing who reported them, but the server operator can see what is posted from their server.</p>\n<h2 id=\"what-the-software-does-about-it\">What the software does about it</h2>\n<p>The app is built so that the rules above are cheap to enforce:</p>\n<ul>\n<li><strong>Warnings, sensitive marking, silencing, take-downs and suspensions</strong> — five actions in order of weight, each recorded against the moderator who took it, four of them reversible.</li>\n<li><strong>A review queue</strong> for a first post and for posts that trip the spam rules. A direct message is never held.</li>\n<li><strong>Domain blocks</strong> that also clean up what a blocked server already sent.</li>\n<li><strong>Reports</strong> arrive from two directions — a local person reporting through a client, and a peer server reporting on behalf of one of its own users — and land in the same queue for the administrators and the delegated group.</li>\n<li><strong>Everything lands in Nextcloud&#39;s audit log</strong> where the audit app is enabled, next to every other administrative action.</li>\n</ul>\n<p>See <a href=\"/protect\">How Aloha Social protects you</a> for the full list, and the <a href=\"/docs/admin-moderating\">moderating chapter</a> for the exact behaviour.</p>\n<h2 id=\"what-you-can-do-for-yourself\">What you can do for yourself</h2>\n<ul>\n<li><strong>Filtered words</strong> fold or hide matching posts in every timeline, and can expire on their own.</li>\n<li><strong>Who may reach you</strong> holds messages from strangers, new accounts and unsolicited private mentions in a review queue instead of ringing the bell.</li>\n<li><strong>Mute a conversation</strong> without leaving it; <strong>hide a whole server</strong> without asking an administrator.</li>\n<li><strong>Block</strong> severs a relationship in both directions and hides somebody everywhere, and they are never told.</li>\n<li><strong>Report</strong> a post or an account. Reports about remote accounts are relayed without exposing you.</li>\n</ul>\n<h2 id=\"reporting\">Reporting</h2>\n<p>The report button on a post or a profile sends it to the moderators of your server. Say what the problem is; a sentence is enough. Where the account belongs to another server, your server forwards the report and keeps your identity off it.</p>\n<p>Moderators cannot act on what they cannot see — if a post breaks the rules of <em>their</em> server but not yours, the useful report goes to them. The <a href=\"/servers\">find a server</a> pages link to each server&#39;s own rules and contact.</p>\n<h2 id=\"for-people-running-a-server\">For people running a server</h2>\n<p>Registration can be open, approval-based or invitation-only. Social-only accounts exist so that members of the public can sign up for Aloha Social alone, with no access to files, chat or anything else. Spam rules and first-post review are per-server switches, and the moderation settings are in the administration page.</p>\n<p>The <a href=\"/docs/admin\">administration guide</a> covers all of it, and <a href=\"/install\">the installation guide</a> covers getting a server to the point where these rules matter.</p>\n<h2 id=\"changing-these-rules\">Changing these rules</h2>\n<p>This page describes the baseline the software is built around. Your server&#39;s operator may publish stricter rules and does not need permission to do so. If you run a server, publish your rules where people can find them before they sign up — the <a href=\"/servers\">find a server</a> listing gives you a place for them.</p>\n","toc":[{"id":"rules-for-using-aloha-social","text":"Rules for using Aloha Social","level":2},{"id":"the-baseline","text":"The baseline","level":2},{"id":"what-the-software-does-about-it","text":"What the software does about it","level":2},{"id":"what-you-can-do-for-yourself","text":"What you can do for yourself","level":2},{"id":"reporting","text":"Reporting","level":2},{"id":"for-people-running-a-server","text":"For people running a server","level":2},{"id":"changing-these-rules","text":"Changing these rules","level":2}]}];

export const SITE_PAGE_BY_PATH: Record<string, SitePage> = Object.fromEntries(
  SITE_PAGES.map((page) => [page.path, page]),
);
